B.data_structures:
classDiagram
  class User { +id +email +encryptedKeys[] +paperCapital +paperRiskPct }
  class Run { +id +userId +ticker +date +analysts[] +provider +model +status +reports[] }
  class Decision { +runId +rating +pending|resolved +realizedReturn +alpha +reflection }
  class TradeCard { +runId +trigger +instrument +delta +entry +stopLoss +t1 +t2 +lots +maxLoss +simulated }
  class PaperTrade { +id +userId +cardId +entryPremium +exitPremium +outcome +pnlAfterCharges }
  class Ensemble { +id +memberRunIds[] +metaJudge }
  class Trigger { +id +userId +condition +lastFiredAt }
  User *-- Run
  Run *-- Decision
  Run *-- TradeCard
  TradeCard *-- PaperTrade
  User *-- Ensemble
  User *-- Trigger
